begin;
do $$
declare uid uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); other_sid uuid:=gen_random_uuid();
  factor uuid:=gen_random_uuid(); ip text:=encode(extensions.gen_random_bytes(32),'hex'); agent text:=repeat('b',64); value jsonb; n integer;
begin
  insert into auth.users(id,email,email_confirmed_at) values(uid,'password-stepup-'||uid||'@example.invalid',clock_timestamp());
  insert into public.users(id,email,username,full_name,role,status) values(uid,'password-stepup-'||uid||'@example.invalid','password-stepup-'||uid,'Password rollback fixture','admin','active') on conflict(id) do update set role='admin',status='active';
  insert into auth.mfa_factors(id,user_id,factor_type,status,friendly_name,secret,created_at,updated_at) values(factor,uid,'totp','verified','Rollback fixture','not-a-live-secret',clock_timestamp(),clock_timestamp());
  insert into auth.sessions(id,user_id,aal,factor_id,created_at,updated_at) values(sid,uid,'aal2',factor,clock_timestamp()-interval '10 minutes',clock_timestamp()),(other_sid,uid,'aal1',null,clock_timestamp(),clock_timestamp());
  insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'totp',clock_timestamp()-interval '10 minutes',clock_timestamp()-interval '10 minutes');
  insert into management_security.accounts(user_id,mfa_required,recovery_ack_at) values(uid,true,clock_timestamp()) on conflict(user_id) do update set mfa_required=true,recovery_ack_at=clock_timestamp();
  insert into management_security.sessions(session_id,user_id,ip_hash,agent_hash,password_verified_at,email_required,email_verified_at,email_identity_hash,authorized_at,expires_at)
    values(sid,uid,ip,agent,clock_timestamp()-interval '10 minutes',true,clock_timestamp(),management_security.email_hash(uid),clock_timestamp(),clock_timestamp()+interval '5 hours');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid,'aal','aal2')::text,true);
  if not public.security_management_access_allowed(false) or public.security_management_access_allowed(true) then raise exception 'Old MFA must allow reading and deny writing without password proof'; end if;
  if has_function_privilege('authenticated','public.security_password_stepup(text,uuid,uuid,text,text)','EXECUTE') or has_function_privilege('anon','public.security_password_stepup(text,uuid,uuid,text,text)','EXECUTE') then raise exception 'Browser can forge password proof'; end if;
  begin perform public.security_password_stepup('confirm',uid,sid,ip,agent); raise exception 'Caller bypassed service-only proof'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claims',jsonb_build_object('role','service_role')::text,true);
  if public.security_password_stepup('status',uid,sid,ip,agent)->>'recent_password'<>'false' then raise exception 'Proof existed before confirmation'; end if;
  for n in 1..5 loop
    value:=public.security_password_stepup('prepare',uid,sid,ip,agent);
    if value->>'ok'<>'true' then raise exception 'Rate limit prematurely rejected attempt %',n; end if;
  end loop;
  value:=public.security_password_stepup('prepare',uid,sid,ip,agent);
  if value->>'ok'<>'false' or value->>'reason'<>'rate' then raise exception 'Sixth password attempt bypassed rate limit'; end if;
  value:=public.security_password_stepup('confirm',uid,sid,ip,agent);
  if value->>'ok'<>'true' then raise exception 'Valid server confirmation rejected'; end if;
  if public.security_password_stepup('status',uid,sid,ip,agent)->>'recent_password'<>'true' then raise exception 'Recent proof unavailable'; end if;
  if not exists(select 1 from auth.sessions where id=sid and aal='aal2') then raise exception 'Confirmation replaced AAL2 session'; end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid,'aal','aal2')::text,true);
  if not public.security_management_access_allowed(true) then raise exception 'Password proof did not allow sensitive action'; end if;
  update management_security.sessions set password_confirmed_at=clock_timestamp()-interval '6 minutes' where session_id=sid;
  if public.security_management_access_allowed(true) then raise exception 'Expired proof accepted'; end if;
  update management_security.sessions set password_confirmed_at=clock_timestamp(),password_confirmation_ip=repeat('c',64) where session_id=sid;
  if public.security_management_access_allowed(true) then raise exception 'Wrong IP proof accepted'; end if;
  update management_security.sessions set password_confirmation_ip=ip,password_confirmation_agent=repeat('c',64) where session_id=sid;
  if public.security_management_access_allowed(true) then raise exception 'Wrong agent proof accepted'; end if;
  update management_security.sessions set password_confirmation_agent=agent,recovery_only=true where session_id=sid;
  if public.security_management_access_allowed(true) then raise exception 'Recovery session bypassed guard'; end if;
  update management_security.sessions set recovery_only=false,email_verified_at=null where session_id=sid;
  if public.security_management_access_allowed(true) then raise exception 'Password proof bypassed email verification'; end if;
  update management_security.sessions set email_verified_at=clock_timestamp() where session_id=sid;
  update management_security.accounts set recovery_ack_at=null where user_id=uid;
  if public.security_management_access_allowed(true) then raise exception 'Password proof bypassed recovery acknowledgement'; end if;
  update management_security.accounts set recovery_ack_at=clock_timestamp() where user_id=uid;
  update public.users set status='inactive' where id=uid;
  if public.security_management_access_allowed(true) then raise exception 'Password proof bypassed inactive account'; end if;
  update public.users set status='active' where id=uid;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',other_sid,'aal','aal2')::text,true);
  if public.security_management_access_allowed(true) then raise exception 'Proof from another session accepted'; end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid,'aal','aal1')::text,true);
  if public.security_management_access_allowed(true) then raise exception 'Password proof bypassed AAL1'; end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','service_role')::text,true);
  if public.security_password_stepup('confirm',uid,other_sid,ip,agent)->>'ok'<>'false' then raise exception 'Unregistered AAL1 session confirmed'; end if;
  update management_security.sessions set expires_at=clock_timestamp()-interval '1 second' where session_id=sid;
  if public.security_password_stepup('confirm',uid,sid,ip,agent)->>'ok'<>'false' then raise exception 'Expired session confirmed'; end if;
end $$;
select 'Password proof, rate, live AAL2, session binding, email and recovery checks passed; fixtures rolled back' verification;
rollback;
